/* @autogenerated */
package net.civeira.phylax.feature.template.page.domain;

import java.util.Optional;

import lombok.Builder;
import lombok.Value;

/**
 * Result of a {@link PageDecoration}.
 *
 * <p>
 * {@code html} is empty when there is no theme layout for the page: the caller then wraps
 * {@code body} with its own built-in fallback, using {@code themeName} and {@code themeAssetsPath}
 * for the static assets.
 */
@Value
@Builder
public class DecoratedPage {
  /** Full page rendered with the theme layout, if there is one. */
  Optional<String> html;
  /** Page template rendered with the fragment (the fragment itself if there is no template). */
  String body;
  /** Theme resolved, or the default theme. */
  String themeName;
  /** Path the theme assets are served from. */
  String themeAssetsPath;

  /** The layout came from a theme (not from the fallback). */
  public boolean isThemed() {
    return html.isPresent();
  }
}
